question.solution:
import math


def ok(data=None, message='ok'):
    return {'code': 0, 'message': message, 'data': data}


def fail(message, code=1001, data=None):
    return {'code': code, 'message': message, 'data': data}


def paginate(items, page=1, size=10):
    items = list(items or [])
    page = max(1, int(page))
    size = max(1, int(size))
    total = len(items)
    pages = math.ceil(total / size) if total else 0
    start = (page - 1) * size
    return ok({
        'list': items[start:start + size],
        'total': total,
        'page': page,
        'size': size,
        'pages': pages,
    })


def safe_call(fn, *args, **kwargs):
    try:
        return fn(*args, **kwargs)
    except ValueError as exc:
        return fail(str(exc) or '参数不合法')
    except Exception as exc:
        print(f'[error] {type(exc).__name__}: {exc}')
        return fail('服务器内部错误', code=500)


def divide(a, b):
    if b == 0:
        raise ValueError('除数不能为 0')
    return ok(a / b)


print(paginate(list(range(1, 26)), page=3, size=10))
print(paginate([], page=1, size=10))
print(safe_call(divide, 6, 2))
print(safe_call(divide, 6, 0))
print(safe_call(divide, 'x', 2))
